L["Where to find it"] = "Kde to najít"
L["Where to get it"] = "Kde to získat"
L["Where to level next"] = "Kde dál levelovat"
L["Where you dragged the guide window, the arrow, the buttons, the alerts and the trackers, and Move frames' grid. Another screen may need them moved again."] = "Kam jsi přetáhl okno návodu, šipku, tlačítka, upozornění a trackery, a mřížka Přesunout rámy. Na jiné obrazovce může být potřeba je posunout znovu."
L["Where: %s"] = "Kde: %s"
